'use strict';
/* ========================================================================
   EDITABLE QUESTION & STORY BANK
   Every decision has dialogue, evidence, 4 responses, feedback and a revision
   note. Exactly ONE response must have ok:true. Add chapters/decisions here;
   the interface, checkpoint map and results calculate totals automatically.
   These are ORIGINAL fictional practice cases, not the lecturer's own notes.
   Basis: IESBA conceptual framework / audit independence (Part 4A).
   ======================================================================== */
const CHAPTERS = [
  {title:'The welcome gift',place:'Meridian · Executive floor',time:'23:41',theme:'Self-interest',summary:'A generous welcome conceals a personal financial conflict.'},
  {title:'Your own reflection',place:'Meridian · Finance studio',time:'00:16',theme:'Self-review',summary:'The client wants the audit firm to mark its own work.'},
  {title:'A familiar face',place:'Secure line · Audit office',time:'01:03',theme:'Familiarity',summary:'An undisclosed relationship changes the team’s independence.'},
  {title:'The investor broadcast',place:'Meridian · Boardroom',time:'02:12',theme:'Advocacy',summary:'A microphone can turn an independent auditor into a promoter.'},
  {title:'Pressure in the dark',place:'Meridian · Records archive',time:'03:28',theme:'Intimidation',summary:'The file is ready. Someone wants it to disappear.'},
  {title:'The last signature',place:'Meridian · Audit committee',time:'05:47',theme:'New-case application',summary:'A new conflict tests whether you can apply the whole framework.'}
];
const o=(text,why,ok=false)=>({text,why,ok});
const DECISIONS = [
 {id:'shares-threat',chapter:0,person:'vale',room:'office',type:'Identify the threat',topic:'Self-interest',
  dialogue:['Welcome, {name}. Before we start, I’ve arranged a small thank-you. Meridian shares. They’re already in your personal trading account.','You’ll be on our audit team tomorrow. Think of it as a reason to believe in our future.'],
  narrative:'The CFO slides a trading confirmation across the desk. The transfer is in your name.',
  evidence:{title:'Personal share transfer',body:'Recipient: {name}\nIssuer: Meridian Group — your audit client\nHolding: Direct shares in the auditor’s own account\nAudit role: Member of the engagement team\nNote: The CFO calls the amount “small”.'},
  question:'What is the main independence threat created by the shares?',
  options:[o('Self-interest: my own investment could influence my audit judgments.','Your personal financial stake links your interests to the client’s results.',true),o('Self-review: I would be auditing work that I prepared.','The facts show an investment, not your prior accounting work.'),o('Advocacy: holding shares means I have already promoted an investment offer.','An investment alone is not the act of promoting a client’s position.'),o('No threat: the CFO says the holding is small.','A direct financial interest held by an audit team member is prohibited; “small” does not cure it.')],
  explanation:'Your own shares create a self-interest threat: you could benefit from favourable client results. Audit team members must not hold a direct financial interest in the audit client. Independence includes how the situation would appear to an informed observer.',
  note:'Revise: self-interest; direct financial interests; IESBA Section 510.',failure:'custody',success:'You name the conflict. Vale’s smile tightens.'},
 {id:'shares-action',chapter:0,person:'maya',room:'office',type:'Choose the response',topic:'Self-interest',
  dialogue:['You were right to stop, {name}. The shares cannot stay in your account while you remain on this audit team.','We must stop the conflicted work, notify the firm’s ethics partner and resolve this under the firm’s breach procedures. A promise to be objective is not enough.'],
  narrative:'Maya joins the secure video link. The trading confirmation is now in the independence file.',
  evidence:{title:'Independence incident log',body:'Direct holding confirmed. You have not yet performed the audit work.\nRequired: Prompt escalation, removal of the prohibited interest or removal from the audit team, and the firm’s assessment of any breach and work affected.\nClient consent does not override independence requirements.'},
  question:'What do you do now?',
  options:[o('Keep the shares but ask another auditor to review my work.','Review alone does not remove the prohibited direct holding.'),o('Stop work and tell the ethics partner; promptly dispose of the holding or leave the audit team, with the breach assessed.','This removes the prohibited circumstance and triggers the necessary firm response.',true),o('Ask Vale to sign a consent form allowing me to keep the shares.','The client cannot waive the auditor’s independence rules.'),o('Move the shares to my spouse and continue as normal.','An immediate family member’s direct holding also creates a prohibited situation for an audit team member.')],
  explanation:'Address the prohibited circumstance, not just its symptoms. Disclose promptly to the firm, stop affected work and arrange disposal or removal from the team. The firm must assess the breach and any consequences for the engagement. A reviewer is not a substitute for removing a prohibited holding.',
  note:'Revise: eliminating a threat versus applying a safeguard; Sections 400 and 510.',failure:'custody',success:'Maya logs the incident. The shares are returned before you rejoin the case.'},
 {id:'gift-action',chapter:0,person:'vale',room:'office',type:'A second offer',topic:'Self-interest',
  dialogue:['No shares, then. How about a luxury weekend for you and your partner? No paperwork. Just approve our inventory number before you go.','It’s a reward for being reasonable. Surely a gift is different from shares?'],
  narrative:'A hotel booking appears on your phone. It is explicitly tied to your audit conclusion.',
  evidence:{title:'The weekend booking',body:'Private villa, flights and meals for two.\nPaid by: Meridian Group\nCondition in message: “Approve the inventory figure first.”\nThe offer is neither trivial nor inconsequential and is intended to influence you.'},
  question:'Which response protects your independence?',
  options:[o('Accept it after the audit report is signed.','Delaying acceptance does not remove the improper influence or reward.'),o('Accept half of it and disclose the other half.','Reducing the gift does not make this inducement acceptable.'),o('Decline, preserve the message and escalate the inducement to the engagement partner.','Declining and reporting confronts the influence rather than hiding it.',true),o('Let a colleague accept it for me.','An indirect gift still exposes you and the team to improper influence.')],
  explanation:'An expensive, conditional gift can influence professional judgment. Decline it, document the offer and escalate. Audit teams must not accept client gifts or hospitality unless trivial and inconsequential; an inducement with intent to improperly influence must not be accepted even if small.',
  note:'Revise: gifts and hospitality, improper inducements; Sections 340 and 420.',failure:'custody',success:'You reject the booking. A message arrives: “Go to Finance. Ask who built the model.”'},
 {id:'own-work',chapter:1,person:'iris',room:'office',type:'Identify the threat',topic:'Self-review',
  dialogue:['Our asset valuation was prepared by your firm’s advisory team last month. The amount is material to our financial statements.','Now your audit team must evaluate that same valuation. I hope your colleagues were right.'],
  narrative:'Two folders carry the same firm logo: “Valuation prepared” and “Audit evidence”.',
  evidence:{title:'The valuation work trail',body:'Client: Meridian Group, a privately held non-public-interest entity for this case.\nPrior work: Audit firm’s advisory team prepared an asset valuation.\nCurrent work: Audit team evaluates that valuation.\nThe firm must assess relevant service restrictions, judgments and materiality before deciding whether the arrangement is permissible.'},
  question:'What threat arises from evaluating the firm’s own valuation work?',
  options:[o('Familiarity: the controller has a friendly tone.','The important fact is the firm evaluating its own previous work, not a close relationship.'),o('Self-review: the audit may be reluctant to challenge the firm’s earlier judgment.','Correct. The firm’s prior work is now part of what it must evaluate.',true),o('Intimidation: all material valuations are threats.','Materiality matters, but no pressure is described in this decision.'),o('None: different departments automatically make the work independent.','Separate departments do not automatically eliminate self-review or override restrictions.')],
  explanation:'This is self-review: an audit judgment could be biased by the firm’s earlier work. Assess the exact service and applicable restrictions. Do not assume that separate teams make every valuation service permissible; materiality and subjectivity can trigger prohibitions.',
  note:'Revise: self-review and non-assurance services; Sections 600 and 603.',failure:'dismissed',success:'Iris opens the next folder. It contains an unsigned management approval.'},
 {id:'management-role',chapter:1,person:'iris',room:'office',type:'Safeguard or prohibition?',topic:'Self-review',
  dialogue:['Our finance director left. Could your audit team choose the impairment assumptions, decide the final valuation and authorise the journal?','We’ll call it “audit assistance”. I can add my signature afterwards without checking it.'],
  narrative:'The proposed work is a management decision, not merely technical advice.',
  evidence:{title:'Draft responsibility letter',body:'Requested audit-team tasks:\n• Choose significant assumptions\n• Decide the final accounting amount\n• Authorise the journal entry\nClient involvement: A signature only; no competent evaluation or decision.\nThe label “assistance” does not change who actually makes the decisions.'},
  question:'Can an independent reviewer make this proposed management role acceptable?',
  options:[o('Yes. Add a reviewer and make the decisions for the client.','A reviewer cannot make assuming management responsibility for an audit client acceptable.'),o('Yes. A client signature means the audit team is no longer responsible.','A rubber-stamp signature is not genuine management decision-making.'),o('No. Decline the management role; competent client management must make and own the decisions.','Correct. The audit firm must not assume management responsibility.',true),o('Yes. Change the invoice description to consulting.','The substance of the work matters, not the invoice description.')],
  explanation:'The audit firm must not assume management responsibility for its audit client. Decline that role. Competent client management must genuinely evaluate advice, make the decisions and take responsibility. Even then, the firm must separately check whether any proposed advisory service is permitted.',
  note:'Revise: management responsibility; Section 600. Not every threat has a usable safeguard.',failure:'custody',success:'You refuse to become management. Iris keeps her access card on the desk.'},
 {id:'no-safeguard',chapter:1,person:'maya',room:'office',type:'Apply the framework',topic:'Framework',
  dialogue:['We have assessed a separate proposed service. It is prohibited by the applicable independence rules. The client insists we do it anyway.','What belongs in our response? Be precise: a safeguard cannot override an express prohibition.'],
  narrative:'A red flag sits beside the service in the ethics register. The audit itself has not yet been accepted for the next year.',
  evidence:{title:'Ethics review conclusion',body:'Service status: Prohibited under the applicable independence rules.\nManagement request: Proceed anyway, with a second reviewer.\nDecision required: Whether to accept this prohibited additional work.\nDo not confuse reducing a permissible threat with overriding an express prohibition.'},
  question:'What is the correct response to this proposed service?',
  options:[o('Decline the prohibited service; if independence for the audit cannot be maintained, do not accept or continue the audit.','Correct. A reviewer or client consent cannot override a prohibition.',true),o('Do it because any second partner is an adequate safeguard.','A review is not permission to perform prohibited work.'),o('Do it if the audit committee gives written consent.','Governance approval cannot waive an express independence prohibition.'),o('Do it now and assess independence after signing.','Assessment must happen before accepting the work, not after the damage is done.')],
  explanation:'Use the framework before accepting work. Where work is expressly prohibited, decline it. For other threats, eliminate the cause or use effective safeguards. If threats cannot be reduced to an acceptable level, decline or end the relevant activity or engagement, subject to applicable requirements.',
  note:'Revise: identify → evaluate → address; IESBA Section 120 and Part 4A.',failure:'dismissed',success:'Maya saves the service refusal. “Now check who is on our team.”'},
 {id:'family-threat',chapter:2,person:'noah',room:'office',type:'Identify the threat',topic:'Familiarity',
  dialogue:['I should have told you earlier. Iris, the financial controller, is my sister. She has significant influence over Meridian’s accounting records.','I’m testing the estimates she prepared. I know she wouldn’t mislead us.'],
  narrative:'Noah has relied on Iris’s explanations without challenging a key assumption.',
  evidence:{title:'Relationship declaration',body:'Auditor: Noah, engagement team member\nClient officer: Iris, Noah’s sister\nRole: Financial controller with significant influence over accounting records\nAssignment: Noah audits Iris’s estimates\nA sibling is close family under the Code. Evaluate the relationship and roles; do not treat all relationships identically.'},
  question:'What is the clearest threat in Noah’s statement?',
  options:[o('Advocacy, because Iris prepares accounts.','Preparing client accounts is not the same as the auditor promoting the client.'),o('Self-review, because all estimates are reviewed.','Noah is reviewing his sister’s work, not his own or his firm’s earlier work.'),o('No threat if Noah has known Iris for a long time.','A close relationship can increase sympathy and reduce scepticism.'),o('Familiarity: the close family relationship may make Noah too trusting.','Correct. His words show sympathy replacing professional challenge.',true)],
  explanation:'A close family relationship can create familiarity and potentially self-interest or intimidation threats. Here the clearest issue is reduced scepticism about a sibling’s estimates. Consider the relationship, the client role and the auditor’s responsibilities rather than treating disclosure alone as a solution.',
  note:'Revise: familiarity; close family relationships; Section 521.',failure:'dismissed',success:'Noah exhales. “I thought being family meant I understood her better.”'},
 {id:'family-action',chapter:2,person:'maya',room:'office',type:'Choose the response',topic:'Familiarity',
  dialogue:['We have assessed this particular sibling relationship and assignment as creating an unacceptable threat. We can replace Noah on the engagement.','His completed estimates work also needs an objective review. What should we do?'],
  narrative:'You have the authority to propose a team change. A suitable replacement is available.',
  evidence:{title:'Team reassignment plan',body:'Assessed threat: Not at an acceptable level in these circumstances\nAvailable action: Remove Noah from the engagement and assign an independent replacement\nWork affected: Estimates tested by Noah\nAdditional action: Appropriate reviewer evaluates the work already performed\nFor other relationships, the outcome depends on the facts and Code requirements.'},
  question:'Which plan addresses the facts most effectively?',
  options:[o('Keep Noah and ask Iris to promise she is honest.','A client promise does not address the auditor’s relationship or biased work.'),o('Tell Noah to try harder but leave his work unchecked.','An instruction to be objective is not an effective response to this assessed threat.'),o('Remove Noah, appoint the replacement and arrange an appropriate review of his affected work.','Correct. The relationship is removed from the audit assignment and past work is evaluated.',true),o('Only add the relationship to our register and continue unchanged.','Documentation matters, but disclosure alone does not reduce the assessed threat.')],
  explanation:'In this case, removing Noah eliminates his conflicting role on the engagement. An appropriate reviewer should evaluate his affected work. The team must record the assessment and actions. Disclosure alone does not resolve an unacceptable threat.',
  note:'Revise: actions addressing relationships; distinguish disclosure, elimination and review.',failure:'dismissed',success:'The replacement takes over. In Noah’s file, you find an investor invitation.'},
 {id:'appearance',chapter:2,person:'noah',room:'office',type:'Explain your judgment',topic:'Framework',
  dialogue:['I really was trying to be fair. If I know I’m honest, why does it matter how this looks?','Would an outsider really need to know about my sister?'],
  narrative:'Noah wants to understand the reasoning, not just the rule.',
  evidence:{title:'Independence assessment',body:'Independence of mind: Ability to reach a judgment without compromising influences.\nIndependence in appearance: Avoiding facts that would lead a reasonable, informed third party to conclude integrity, objectivity or professional scepticism has been compromised.\nA private belief in your honesty is not the full test.'},
  question:'Which explanation is strongest?',
  options:[o('Your honest intention is enough; outside perceptions never matter.','Independence in appearance also matters.'),o('We need both independent judgment and circumstances that an informed third party would regard as independent.','Correct. Intention alone cannot establish independence in appearance.',true),o('Any outsider’s suspicion automatically proves a legal offence.','The test is a reasonable and informed third party, not any suspicion or an automatic legal conclusion.'),o('We only assess appearances after the report has been issued.','Independence must be assessed and maintained throughout the relevant period.')],
  explanation:'Independence involves both mind and appearance. Ask what a reasonable and informed third party, knowing the relevant facts, would conclude. Good intentions are important but cannot by themselves remove a conflict.',
  note:'Revise: independence of mind and appearance; reasonable and informed third-party test.',failure:'dismissed',success:'Noah agrees to the reassignment. The investor broadcast is about to begin.'},
 {id:'advocacy-threat',chapter:3,person:'vale',room:'boardroom',type:'Identify the threat',topic:'Advocacy',
  dialogue:['Our investors trust your firm. Join my broadcast and tell them Meridian’s shares are a fantastic buy.','We’ll introduce you as our independent auditor. That should settle their doubts.'],
  narrative:'A red recording light turns on. The invitation asks you to sell the investment, not explain an audit.',
  evidence:{title:'Broadcast script',body:'Presenter: “Our independent auditor recommends buying Meridian shares today.”\nRequested role: Promote the client’s investment offer\nYour role: Audit engagement team member\nThis is not a neutral explanation of audit scope or an authorised discussion of the auditor’s report.'},
  question:'What is the main threat from acting as the investment promoter?',
  options:[o('Advocacy: promoting the client’s position could compromise objectivity.','Correct. An auditor must not become the promoter of the audit client’s shares.',true),o('Self-review: the broadcast revisits the company’s results.','The key act is promotion, not evaluating your previous work.'),o('Familiarity: appearing on camera always creates a close relationship.','A camera does not establish familiarity. The requested promotional role creates advocacy.'),o('No threat because investors like hearing from auditors.','Popularity does not make the requested promotion independent.')],
  explanation:'Promoting an audit client’s shares creates an advocacy threat. The auditor would be aligning with the client’s fundraising position. An independent audit role cannot be combined with acting as a promoter of the audit client’s shares.',
  note:'Revise: advocacy; corporate finance services; Section 610.',failure:'custody',success:'You identify the trap before the live feed starts.'},
 {id:'advocacy-action',chapter:3,person:'vale',room:'boardroom',type:'Choose your words',topic:'Advocacy',
  dialogue:['Just say it once, {name}. We’ll add a disclaimer: “Views are personal.”','The producer is waiting. What do you want your line to be?'],
  narrative:'The producer holds up a cue card with your name under the words “BUY NOW”.',
  evidence:{title:'Producer’s cue card',body:'Proposed line: “As Meridian’s independent auditor, I recommend these shares.”\nProposed disclaimer: “Personal view only.”\nThe role and audience would still connect the promotion to your audit position.\nClient marketing staff can promote their offer without the auditor acting as promoter.'},
  question:'Choose the dialogue that protects independence.',
  options:[o('“I recommend buying, but this is my personal view.”','A disclaimer does not remove the promotional role.'),o('“Pay my firm an extra fee and I can say it.”','An extra fee adds incentive and does not cure advocacy.'),o('“I cannot promote your shares. Remove my name and the auditor endorsement from this script.”','Correct. You decline the prohibited promotional role.',true),o('“Record it now; we can decide whether it was ethical later.”','The role must be assessed before accepting it.')],
  explanation:'Refuse to promote or recommend the client’s shares and stop use of your name as an endorsement. A disclaimer or another fee does not change the substance. Neutral, properly authorised audit communications are different from selling an investment.',
  note:'Revise: substance over labels; why disclaimers cannot cure prohibited advocacy.',failure:'custody',success:'The red light goes dark. Your name disappears from the script.'},
 {id:'communication-record',chapter:3,person:'maya',room:'boardroom',type:'Secure the audit trail',topic:'Framework',
  dialogue:['You refused the broadcast. Good. What should the independence record explain?','Someone reviewing our file needs to understand the facts, the threat and the action — not just see the word “resolved”.'],
  narrative:'Maya opens a blank incident record. Your explanation will become part of the file.',
  evidence:{title:'Independence record template',body:'1. Relevant facts and requested role\n2. Threat and why it matters\n3. Assessment of significance and applicable prohibitions\n4. Action taken and conclusion\n5. Relevant discussions, consultation and follow-up\nA record supports an action; it does not make prohibited conduct permissible.'},
  question:'Which entry gives a meaningful record of this issue?',
  options:[o('“Resolved. The client seems trustworthy.”','This does not explain the facts, threat or action.'),o('“CFO requested a share endorsement; advocacy threatens objectivity; we refused the promotional role and required removal of our endorsement.”','Correct. It links facts, threat and response.',true),o('“Advocacy.”','A label alone does not show how the issue was evaluated or addressed.'),o('“Client approved our independence.”','The client cannot determine or waive the audit firm’s compliance.')],
  explanation:'Record enough for a reviewer to understand the judgment: what happened, which threat arose, why it matters and what action addressed it. Include consultation and relevant conclusions. Merely naming a threat or obtaining client consent is inadequate.',
  note:'Revise: scenario application — fact → threat → implication → action.',failure:'dismissed',success:'The incident record is sealed. A new message: “Archive. Come alone.”'},
 {id:'intimidation-threat',chapter:4,person:'vale',room:'archive',type:'Identify the threat',topic:'Intimidation',
  dialogue:['If you keep questioning our inventory, I’ll get your firm dismissed. I know people who can end your career.','Remove the exception from your file and we can both leave this room.'],
  narrative:'The archive is almost empty. You keep the secure line to Maya open.',
  evidence:{title:'Recorded threat',body:'CFO demand: Delete an audit exception\nPressure: Dismissal of the firm and damage to your career\nAudit issue: Still unresolved\nThere is actual pressure to deter you from acting objectively. Preserve the record; do not surrender the audit file.'},
  question:'What is the main threat from the CFO’s pressure?',
  options:[o('Intimidation: threatened consequences may deter objective action.','Correct. The threats are being used to influence your audit judgment.',true),o('Familiarity: the CFO knows people in the profession.','The operative fact is coercive pressure, not a close relationship.'),o('Self-review: he asks me to change a file.','Changing a file is not, by itself, evaluating your own prior non-audit work.'),o('No threat until the CFO actually gets me dismissed.','Actual or perceived pressure can create intimidation before a dismissal occurs.')],
  explanation:'Actual or perceived pressure can create intimidation. A threatened dismissal or career consequence may deter an auditor from challenging management. Recognise and escalate the pressure; do not allow it to determine the audit conclusion.',
  note:'Revise: intimidation, including threats to employment or the engagement.',failure:'death',success:'You recognise the pressure. You do not touch the exception.'},
 {id:'pressure-action',chapter:4,person:'maya',room:'archive',type:'Choose the response',topic:'Intimidation',
  dialogue:['I heard that, {name}. Leave the isolated room and stay on the line. We will involve the engagement leadership, ethics partner and audit committee.','Keep the evidence secure through approved channels. The accounting issue still needs proper audit work and an appropriate reporting response.'],
  narrative:'The guarded lobby is nearby. An anonymous message offers to “settle this” on the roof alone.',
  evidence:{title:'Secure escalation route',body:'Available: Guarded lobby, engagement partner, ethics partner, independent audit committee\nPreserve: Threat message and the original audit evidence using approved secure procedures\nDo not: Delete records, accept coercion or leak confidential client material online\nIn real life, seek emergency help if there is immediate physical danger.'},
  question:'What do you say and do?',
  options:[o('“I’ll delete the exception if you let me leave.”','Deleting evidence gives in to pressure and compromises integrity.'),o('“I’ll post all client files publicly for protection.”','Public disclosure can breach confidentiality; use authorised secure escalation.'),o('“I’ll meet the anonymous sender alone on the roof and hand over the file.”','You abandon the safe route and expose both yourself and the evidence to danger.'),o('“I’m moving to the guarded lobby, preserving the evidence and escalating through the partner and audit committee.”','Correct. You protect safety and evidence while obtaining appropriate support.',true)],
  explanation:'Do not alter your judgment to satisfy threats. Seek safety, preserve evidence securely and escalate to appropriate firm leadership and governance. The firm must evaluate independence and the audit/reporting implications. Public leaks are not a substitute for authorised advice and action.',
  note:'Revise: intimidation response; consultation, governance, confidentiality and secure documentation.',failure:'death',success:'Security escorts you to the lobby. Maya forwards the file to the committee chair.'},
 {id:'pressure-unresolved',chapter:4,person:'maya',room:'archive',type:'A difficult conclusion',topic:'Intimidation',
  dialogue:['Suppose our evaluation concludes that this pressure remains unacceptable and no effective safeguard or elimination action is available.','Meridian is an important client. Does that change what we must do?'],
  narrative:'A large fee is on the line, but the independence assessment cannot be bought.',
  evidence:{title:'Unresolved threat assessment',body:'Assumption for this decision: Threats cannot be eliminated or reduced to an acceptable level by any available effective safeguard.\nClient fee: Important to the firm\nRequired next step: Do not continue unchanged. Consider required legal/professional procedures for declining or ending the engagement.'},
  question:'Which conclusion follows from that assessment?',
  options:[o('Continue because losing a major client is too costly.','The firm’s financial interest cannot justify unacceptable threats.'),o('Add an ethics label to the file and sign anyway.','A label or document is not an effective safeguard.'),o('Decline or end the engagement, following applicable legal and professional requirements.','Correct. If independence cannot be maintained, continuing unchanged is not an option.',true),o('Let the CFO decide whether the firm is independent.','Independence is the firm’s responsibility, not the CFO’s choice.')],
  explanation:'When the threat cannot be eliminated or reduced to an acceptable level, decline or end the relevant activity or engagement, following applicable requirements. An important fee does not justify continuing without independence. Consultation helps determine the required procedures.',
  note:'Revise: the final step of the conceptual framework; no effective safeguard means do not proceed unchanged.',failure:'custody',success:'You refuse to trade independence for a fee. At dawn, the committee calls.'},
 {id:'new-case-threat',chapter:5,person:'chair',room:'boardroom',type:'Final test · New example',topic:'Self-interest',
  dialogue:['Before we decide the way forward, a new issue: a member of next year’s proposed audit team has a spouse who directly owns Meridian shares.','The spouse will keep the shares. The team member says they have separate bank accounts, so there is no problem.'],
  narrative:'This was not the CFO’s gift. Apply what you learned to a new person and a new route to the same conflict.',
  evidence:{title:'New-year team declaration',body:'Proposed team member: Audit senior\nInvestor: The senior’s spouse (immediate family)\nInvestment: Direct financial interest in the audit client\nSpouse’s plan: Retain the shares\nSeparate bank accounts do not remove the immediate-family relationship.'},
  question:'What is the main independence threat in this new example?',
  options:[o('Only familiarity because the investor is a spouse.','The relevant client connection is a financial interest; a spouse relationship alone is not a relationship with client management.'),o('Self-interest through an immediate family member’s direct financial interest.','Correct. The new route to the conflict is the spouse’s direct holding.',true),o('Advocacy because the spouse owns shares.','Ownership alone is not promoting a client’s investment.'),o('None, because their accounts are separate.','Separate accounts do not remove the immediate-family financial-interest restriction.')],
  explanation:'This is a self-interest threat through immediate family. The audit team member’s spouse must not hold a direct financial interest in the audit client while the member is on that team. Separate bank accounts do not make the conflict disappear.',
  note:'Transfer test: immediate family financial interests; Section 510.',failure:'dismissed',success:'The chair nods. “Now give me an action that actually works.”'},
 {id:'new-case-action',chapter:5,person:'chair',room:'boardroom',type:'Final test · Action',topic:'Self-interest',
  dialogue:['The spouse will not dispose of the shares. We can select a different audit senior.','Which plan removes this prohibited situation from the proposed audit team?'],
  narrative:'You must choose an action, not simply promise more care.',
  evidence:{title:'Available team decision',body:'Spouse will retain the direct holding.\nIndependent replacement auditor: Available\nProposed senior: Has not joined the new engagement\nClient consent, immateriality or a second reviewer cannot override the direct-interest rule.'},
  question:'What should the firm do with the proposed team assignment?',
  options:[o('Keep the senior and get client approval.','Client consent does not remove the prohibited situation.'),o('Keep the senior because the spouse’s investment is small.','The direct-interest restriction is not cured by calling the holding small.'),o('Use the independent replacement and do not assign the conflicted senior to this audit team.','Correct. With the spouse retaining the holding, remove the conflicted assignment.',true),o('Keep the senior and check independence at the end of the audit.','The conflict must be resolved before assignment, not postponed.')],
  explanation:'Since the spouse will retain the direct financial interest, do not put the senior on this audit team. Use the independent replacement and document the assessment. This eliminates the prohibited circumstance for the team rather than relying on a reviewer or a promise.',
  note:'Revise: eliminate the cause; reviewers are not a universal remedy.',failure:'custody',success:'The new team is independent. One question remains before sunrise.'},
 {id:'final-framework',chapter:5,person:'chair',room:'boardroom',type:'The last signature',topic:'Framework',
  dialogue:['The committee has removed Vale. Your firm has assessed the issues, resolved the conflicts and obtained appropriate independent reviews.','We now have an independent team. Does that alone mean the financial statements deserve an unmodified audit opinion?'],
  narrative:'Your final decision separates independence from the audit evidence and reporting judgment.',
  evidence:{title:'Final engagement status',body:'Independence: Assessed and resolved for this fictional ending\nAudit evidence: Further procedures still required on inventory and valuation\nAudit opinion: Must depend on sufficient appropriate evidence and the financial reporting conclusions\nAn independent auditor can still need a modified opinion or other response.'},
  question:'What do you tell the chair?',
  options:[o('“Yes. Independence guarantees that every accounting figure is correct.”','Independence is essential, but it is not a substitute for audit evidence.'),o('“Yes. Replacing the CFO means no more testing is needed.”','A management change does not resolve the accounting or evidence issues by itself.'),o('“No. Independence is essential; we must still obtain sufficient appropriate evidence and reach the appropriate audit opinion.”','Correct. You keep the independence assessment and audit conclusion distinct.',true),o('“The committee can choose the opinion it prefers.”','The auditor must reach an evidence-based reporting conclusion, not accept a preferred opinion.')],
  explanation:'Independence supports objective work; it does not prove the accounts are free from material misstatement. Complete the necessary audit procedures and form the appropriate opinion from the evidence and applicable reporting requirements. Never promise an unmodified opinion as a reward.',
  note:'Revise: independence, professional scepticism, audit evidence and reporting are connected but distinct.',failure:'dismissed',success:'You close the file without surrendering your judgment. The sun reaches the boardroom.'}
];
/* ====================== END EDITABLE STORY BANK ========================= */

const FIELD_GUIDE = [
 ['Self-interest','A financial or other personal interest might influence judgment. Look for investments, gifts or incentives.','Remove the conflicting interest or role. Direct audit-team financial interests are restricted; a reviewer is not permission to retain a prohibited holding.','Sections 510, 340, 420'],
 ['Self-review','The auditor might favour earlier judgments made by themselves or their firm.','Check service prohibitions first. Where permitted, appropriate independent work/review may help. Never take management responsibility.','Sections 600, 603'],
 ['Familiarity','A close or long relationship can reduce professional scepticism.','Evaluate the particular relationship and roles. Reassign or remove the conflicted member and review affected work as appropriate.','Sections 521, 540'],
 ['Advocacy','Promoting a client’s position may compromise objectivity.','Do not act as a promoter of the audit client’s shares. A “personal view” disclaimer cannot cure the role.','Section 610'],
 ['Intimidation','Actual or perceived pressure might deter objective judgment.','Seek appropriate support, preserve evidence, consult and escalate. If threats cannot be addressed, do not continue unchanged.','Section 120; Part 4A'],
 ['Framework','Identify the facts and threat. Evaluate significance. Address the threat.','Eliminate the circumstance, apply effective safeguards, or decline/end the activity. A safeguard must actually reduce the threat.','Section 120; Part 4A']
];

// Session-only learning data: names and answers are never transmitted or persisted.
const $=id=>document.getElementById(id);
let state={name:'',index:0,line:0,phase:'home',checkpoint:0,attempt:1,first:{},history:[],path:[],inspected:[],failures:0};
let shownOptions=[],toastTimer,restoreFocus=null,pausedPhase=null;
const art=AuditArt.renderer($('sceneCanvas'));
const cover=AuditArt.renderer($('coverCanvas'));cover.set('vale','office');
const prefersReduced=typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches;
$('calmMode').checked=prefersReduced;

const audio=AuditAudio.create({
 onVoiceStart:()=>art.talk(true),onVoiceEnd:()=>art.talk(false),
 onEnabled:()=>{if(state.phase==='dialogue'&&!$('audioDialog').open&&!$('infoDialog').open)speakLine();},
 onPanelOpen:()=>art.talk(false)
});
function speakLine(){const d=DECISIONS[state.index];audio.say(d.person,text(d.dialogue[state.line]));}
function stopTalking(){audio.stopVoice();art.talk(false);}

function text(s){return s.replaceAll('{name}',state.name);}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function el(tag,cls,txt){const n=document.createElement(tag);if(cls)n.className=cls;if(txt!==undefined)n.textContent=txt;return n;}
function display(screen){for(const id of ['home','game','ending'])$(id).hidden=id!==screen;window.scrollTo({top:0,behavior:'instant'});}
function setMotion(value){document.body.classList.toggle('reduced-motion',value);art.reduce(value);cover.reduce(value);$('motionToggle').textContent=value?'Enable animation':'Reduce motion';$('calmMode').checked=value;}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function start(name){audio.stopEffects();stopTalking();pausedPhase=null;$('resumeCase').hidden=true;state={name:name.trim().slice(0,30)||'Auditor',index:0,line:0,phase:'dialogue',checkpoint:0,attempt:1,first:{},history:[],path:[],inspected:[],failures:0};setMotion($('calmMode').checked);audio.set($('startMusic').checked);display('game');renderDecision();}
function renderDecision(){
 const d=DECISIONS[state.index],c=CHAPTERS[d.chapter];state.phase='dialogue';state.line=0;
 if(state.index===DECISIONS.findIndex(x=>x.chapter===d.chapter)){state.checkpoint=state.index;$('checkpointToast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('checkpointToast').hidden=true,4000);}else $('checkpointToast').hidden=true;
 $('chapterNumber').textContent=`CHAPTER ${String(d.chapter+1).padStart(2,'0')} / ${String(CHAPTERS.length).padStart(2,'0')}`;$('chapterTitle').textContent=c.title;$('location').textContent=c.place.toUpperCase();$('sceneTime').textContent=c.time;
 $('playerBadge').textContent=`AGENT ${state.name}`;$('characterName').textContent=AuditArt.people[d.person].name;$('characterRole').textContent=AuditArt.people[d.person].role;
 $('speakerLabel').textContent=AuditArt.people[d.person].name;$('sceneNarrative').textContent=text(d.narrative);$('decisionType').textContent=d.type.toUpperCase();$('decisionCount').textContent=`DECISION ${state.index+1} / ${DECISIONS.length}`;
 $('evidenceTitle').textContent=d.evidence.title;$('evidenceState').textContent=state.inspected.includes(d.id)?'✓':'＋';
 $('progressTrack').replaceChildren(...CHAPTERS.map((x,i)=>{const n=el('span',`progress-node ${i<d.chapter?'done':i===d.chapter?'active':''}`);n.title=`Chapter ${i+1}: ${x.title}`;return n;}));
 $('replayVoice').hidden=false;$('decisionArea').hidden=true;$('feedbackArea').hidden=true;$('dialogueActions').hidden=false;$('choices').replaceChildren();
 $('dialogue').textContent='“'+text(d.dialogue[0])+'”';$('nextLine').textContent=d.dialogue.length>1?'Continue conversation ↳':'Choose my response ↳';art.set(d.person,d.room);speakLine();
}
function nextLine(){if(state.phase!=='dialogue')return;const d=DECISIONS[state.index];if(state.line+1<d.dialogue.length){state.line++;$('dialogue').textContent='“'+text(d.dialogue[state.line])+'”';$('nextLine').textContent='Choose my response ↳';speakLine();}else showChoices();}
function showChoices(){state.phase='choice';$('replayVoice').hidden=true;$('dialogueActions').hidden=true;$('decisionArea').hidden=false;$('question').textContent=text(DECISIONS[state.index].question);shownOptions=shuffle(DECISIONS[state.index].options);
 $('choices').replaceChildren(...shownOptions.map((option,i)=>{const b=el('button','choice');b.type='button';b.append(el('span','',String(i+1)),el('span','',text(option.text)));b.addEventListener('click',()=>answer(option,i,b));return b;}));stopTalking();
 const first=$('choices').querySelector('button');if(first)first.focus({preventScroll:true});
}
function answer(option,position,button){
 if(state.phase!=='choice')return;state.phase=option.ok?'feedback':'failed';const d=DECISIONS[state.index];
 $('choices').querySelectorAll('button').forEach(b=>b.disabled=true);if(button)button.classList.add(option.ok?'selected':'wrong');
 const record={id:d.id,index:state.index,chapter:d.chapter,topic:d.topic,choice:option.text,why:option.why,ok:option.ok,attempt:state.attempt};
 if(!state.first[d.id])state.first[d.id]={...record};state.history.push({...record});
 if(option.ok){state.path.push({...record});$('decisionArea').hidden=true;$('feedbackArea').hidden=false;$('feedbackTitle').textContent=text(d.success);$('feedbackText').textContent=d.explanation;$('feedbackNote').textContent=d.note;$('continueButton').textContent=state.index===DECISIONS.length-1?'Close the case →':'Continue →';$('feedbackArea').focus({preventScroll:true});stopTalking();audio.effect('correct');}else{state.failures++;showEnding(false,record);}
}
function continueGame(){if(state.phase!=='feedback')return;if(state.index===DECISIONS.length-1){showEnding(true);return;}state.index++;renderDecision();$('chapterTitle').setAttribute('tabindex','-1');$('chapterTitle').focus({preventScroll:true});}
function returnCheckpoint(){if(state.phase!=='ending')return;audio.stopEffects();state.index=state.checkpoint;state.path=state.path.filter(r=>r.index<state.checkpoint);state.attempt++;display('game');renderDecision();}
const ENDINGS={
 custody:{label:'BAD ENDING / IN CUSTODY',title:'The signature was a trap.',story:'In this fictional branch, the compromised decision helps Vale conceal the trail. He forges the remaining approvals and points investigators at you. The case ends with you in custody.',icon:'▥'},
 death:{label:'BAD ENDING / SIGNAL LOST',title:'The line goes silent.',story:'In this fictional branch, Vale’s accomplice intercepts you before the evidence is secured. The screen cuts to black. Your auditor does not survive the night. No violence is shown.',icon:'◇'},
 dismissed:{label:'BAD ENDING / CASE CLOSED',title:'Your access is revoked.',story:'In this fictional branch, the unresolved independence failure allows Vale to discredit the audit team. Your firm removes you from the case. The evidence never reaches the committee.',icon:'⊘'}
};
function showEnding(won,failed=null){
 state.phase='ending';stopTalking();audio.effect(won?'win':DECISIONS[state.index].failure);display('ending');$('ending').classList.toggle('failure',!won);const d=DECISIONS[state.index];const ending=won?{label:'GOOD ENDING / INDEPENDENCE PRESERVED',title:`You held the line, ${state.name}.`,story:'The committee receives the protected evidence and removes Vale. Your independent team continues the necessary audit work without promising an opinion. You leave Meridian at sunrise with your judgment intact. Case complete.',icon:'◆'}:ENDINGS[d.failure];
 $('endingLabel').textContent=ending.label;$('endingTitle').textContent=ending.title;$('endingStory').textContent=ending.story;$('endingIcon').textContent=ending.icon;
 $('endingDisclaimer').textContent=won?'Winning means you completed the decision path. Your first-answer results below remain separate from retries.':'Fictional thriller stakes: a wrong answer does not automatically cause imprisonment or death in real audit practice. Read the explanation, then retry from the checkpoint.';
 $('checkpointButton').hidden=won;$('checkpointButton').textContent=`Retry chapter ${d.chapter+1} from checkpoint ↗`;
 const records=Object.values(state.first),correct=records.filter(r=>r.ok).length,completed=state.path.length;
 $('resultStats').replaceChildren(...[[`${correct}/${records.length}`,'First answers correct'],[`${records.length}/${DECISIONS.length}`,'Decisions encountered'],[`${completed}/${DECISIONS.length}`,'Current path completed'],[String(state.failures),'Failed branches / retries available']].map(([a,b])=>{const div=el('div');div.append(el('strong','',a),el('span','',b));return div;}));
 renderImprovement(records,won);renderReview();$('ending').focus({preventScroll:true});
}
function renderImprovement(records,won){const box=$('improvementPlan');box.replaceChildren(el('h3','',won?'Your next step':'Checkpoint debrief'));
 const mistakes=records.filter(r=>!r.ok);if(!mistakes.length){box.append(el('p','',won?'All first answers were correct. Next, write a short justification for a fresh case: fact → threat → implication → action. Explain why a reviewer cannot cure a prohibited activity.':'Your earlier answers were sound. Review the current decision below before returning to the checkpoint.'));return;}
 box.append(el('p','',`You have ${mistakes.length} first-answer decision${mistakes.length===1?'':'s'} to revisit. Retrying helps you learn; it does not replace the first-answer record.`));const ul=el('ul');[...new Set(mistakes.map(r=>r.topic))].forEach(topic=>{const g=FIELD_GUIDE.find(x=>x[0]===topic);ul.append(el('li','',`${topic}: ${g?g[2]:'Separate the independence issue from the evidence and reporting decision.'} Read ${g?g[3]:'your audit evidence notes'}.`));});box.append(ul);
}
function renderReview(){const container=$('answerReview');container.replaceChildren();for(const d of DECISIONS){const first=state.first[d.id];if(!first)continue;const attempts=state.history.filter(r=>r.id===d.id),last=attempts[attempts.length-1],card=el('details',`review-card ${first.ok?'':'needs-work'}`);if(!last.ok)card.open=true;
 const summary=el('summary');summary.append(document.createTextNode(`${DECISIONS.indexOf(d)+1}. ${d.type} · ${d.topic}`),el('span','',first.ok?'FIRST ANSWER CORRECT':'REVISE THIS DECISION'));card.append(summary);const body=el('div');body.append(el('p','',text(d.question)));
 const a=el('p');a.append(el('strong','','Your first response: '),document.createTextNode(text(first.choice)));body.append(a,el('p','',first.why));
 if(attempts.length>1)body.append(el('p','',`Recorded attempts: ${attempts.length}. Latest response: ${text(last.choice)} (${last.ok?'correct':'incorrect'}).`));
 body.append(el('p','correct-answer',`Best response: ${text(d.options.find(x=>x.ok).text)}`),el('p','',d.explanation),el('p','revision',d.note));card.append(body);container.append(card);
 }}
function openDialog(label,content){restoreFocus=document.activeElement;$('modalLabel').textContent=label;$('modalBody').replaceChildren();if(typeof content==='string')$('modalBody').innerHTML=content;else $('modalBody').append(content);if(!$('infoDialog').open)$('infoDialog').showModal();stopTalking();$('closeDialog').focus();}
function guide(){openDialog('FIELD GUIDE / CONTROLS & ETHICS',`<h2>Your independence toolkit.</h2><p><strong>Objective:</strong> Identify the five threats and choose a response that actually addresses the facts. This is an untimed, original cinematic conversation game.</p><ol><li>Read each conversation. Select <strong>Continue conversation</strong>, then choose a response.</li><li>Inspect the evidence card and keep a notebook. The guide is available throughout.</li><li>Use mouse, touch or keyboard. Press <strong>1–4</strong> for a choice, <strong>Enter</strong> to advance dialogue/feedback when no other control is focused, <strong>G</strong> for this guide, and <strong>Escape</strong> to close a panel.</li><li>A correct response advances the case after you read the explanation and select Continue. A wrong response ends that branch. Review it, then retry the chapter checkpoint or start again.</li><li>The first answer to each decision determines learning accuracy. Replays never add duplicate learning points. Unseen decisions are not treated as correct. Speed does not affect results.</li></ol><h3>Meet the cast</h3><p>Victor Vale — client CFO. Maya Tan — engagement partner and ethics contact. Iris Chen — client controller. Noah Lim — colleague. Dr Amara Okafor — independent audit committee chair.</p><h3>The framework</h3><p>Identify → evaluate → address. Eliminate the circumstance, apply effective safeguards, or decline/end the relevant activity. Documentation or client consent alone does not remove an unacceptable threat. Do not use a reviewer to justify prohibited work.</p><div class="guide-grid">${FIELD_GUIDE.map(g=>`<article><h3>${g[0]}</h3><p>${g[1]}</p><p>${g[2]}</p><p><small>Read: ${g[3]}</small></p></article>`).join('')}</div><h3>Scope &amp; story</h3><p>Meridian is a fictional privately held, non-public-interest audit client. Rules for public-interest entities and national requirements can be stricter. These cases are original practice material, not your lecturer’s supplied notes. Death and custody are non-graphic thriller branches, not automatic real-world penalties. The 3D characters are original animated low-poly meshes; no commercial game assets or soundtrack are used.</p><p>Choose from four original suspense tracks in Music &amp; FX. Change the tempo and music, effects and chatter volumes separately. Characters make short gibberish sounds while you read their words. Jail, death, dismissal and victory each have distinct audio cues. Sound off mutes everything. Reduced motion is available on the home screen or beneath the scene. No account, tracking, saved name or backend.</p><p><a href="https://www.ethicsboard.org/iesba-code" target="_blank" rel="noopener">Official IESBA Code ↗</a></p>`);}
function evidence(){if(!['dialogue','choice','feedback'].includes(state.phase))return;const d=DECISIONS[state.index];if(!state.inspected.includes(d.id))state.inspected.push(d.id);$('evidenceState').textContent='✓';const div=el('div');div.append(el('h2','',d.evidence.title));const sheet=el('div','evidence-sheet');sheet.append(el('small','','MERIDIAN / SECURE ENGAGEMENT FILE'),el('h3','',d.evidence.title),el('p','',text(d.evidence.body)));div.append(sheet,el('p','','Use the facts to name the threat, explain its effect and choose an effective response. Inspecting evidence has no time or score penalty.'));openDialog('EVIDENCE / '+(state.index+1),div);}
function notebook(){const div=el('div');div.append(el('h2','','Your evidence notebook'));if(!state.inspected.length)div.append(el('p','','No evidence inspected yet. Open the evidence card beneath a character to add it here.'));
 for(const d of DECISIONS.filter(x=>state.inspected.includes(x.id))){div.append(el('h3','',d.evidence.title),el('p','',text(d.evidence.body)));}openDialog('PERSONAL CASE NOTES',div);}
function caseMap(){const chapter=DECISIONS[state.index].chapter;openDialog('CASE MAP / CHECKPOINTS',`<h2>One night. Six chapters.</h2><p>A checkpoint saves at the start of each chapter. After a failure, replay that chapter. Answers and inspected evidence stay in this session’s notebook.</p>${CHAPTERS.map((c,i)=>`<div class="map-row"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${c.title} ${i<chapter?'✓':i===chapter?'· Current checkpoint':''}</strong><p>${c.summary}</p></div></div>`).join('')}`);}
function downloadReview(){const records=Object.values(state.first),correct=records.filter(x=>x.ok).length;const lines=[`INDEPENDENCE PROTOCOL — AUDIT DEBRIEF`,`Auditor: ${state.name}`,`First answers: ${correct}/${records.length} correct; ${records.length}/${DECISIONS.length} encountered.`,`Path completed: ${state.path.length}/${DECISIONS.length}. Failed branches: ${state.failures}.`,`First answers remain unchanged after checkpoint retries.`,`Original fictional learning case, using the IESBA framework. National rules can be stricter.`,``];
 for(const d of DECISIONS){const r=state.first[d.id];if(!r)continue;lines.push(`${DECISIONS.indexOf(d)+1}. ${text(d.question)}`,`Your first response: ${text(r.choice)} [${r.ok?'CORRECT':'REVISE'}]`,`Why: ${r.why}`,`Best response: ${text(d.options.find(x=>x.ok).text)}`,d.explanation,d.note,``);}
 lines.push('READING','IESBA: https://www.ethicsboard.org/iesba-code','ACCA threats: https://www.accaglobal.com/gb/en/about-us/regulation/ethics/conceptual-framework-ethical-dilemmas.html','ACCA application: https://www.accaglobal.com/uk/en/student/exam-support-resources/professional-exams-study-resources/p7/technical-articles/exam-tech-ethics.html','Also review your lecturer’s independence, ethics, audit evidence and reporting notes.');
 const blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='Independence_Protocol_My_Debrief.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function goHome(){if(state.phase!=='home'&&state.name){pausedPhase=state.phase;$('resumeCase').hidden=false;}state.phase='home';stopTalking();audio.stopEffects();display('home');}
$('startForm').addEventListener('submit',e=>{e.preventDefault();start($('playerName').value);});
$('resumeCase').addEventListener('click',()=>{if(!pausedPhase)return;state.phase=pausedPhase;display(pausedPhase==='ending'?'ending':'game');if(pausedPhase==='dialogue')speakLine();pausedPhase=null;$('resumeCase').hidden=true;});
$('nextLine').addEventListener('click',nextLine);$('continueButton').addEventListener('click',continueGame);$('checkpointButton').addEventListener('click',returnCheckpoint);
$('restartButton').addEventListener('click',()=>start(state.name));$('endingHome').addEventListener('click',goHome);$('homeFromGame').addEventListener('click',goHome);$('brand').addEventListener('click',e=>{e.preventDefault();goHome();});
$('evidenceButton').addEventListener('click',evidence);$('notebookOpen').addEventListener('click',notebook);$('caseOpen').addEventListener('click',caseMap);$('guideOpen').addEventListener('click',guide);$('downloadReview').addEventListener('click',downloadReview);
$('closeDialog').addEventListener('click',()=>$('infoDialog').close());$('infoDialog').addEventListener('close',()=>{if(restoreFocus&&restoreFocus.isConnected)restoreFocus.focus({preventScroll:true});art.talk(false);});
$('audioToggle').addEventListener('click',()=>audio.toggle());$('motionToggle').addEventListener('click',()=>setMotion(!document.body.classList.contains('reduced-motion')));$('calmMode').addEventListener('change',()=>setMotion($('calmMode').checked));
$('replayVoice').addEventListener('click',async()=>{if(state.phase!=='dialogue'||!audio.settings().chatter)return;const ready=audio.isReady();if(await audio.set(true)){if(ready&&state.phase==='dialogue')speakLine();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&audio.isOn())audio.set(false);});
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||e.ctrlKey||e.metaKey||e.altKey)return;if($('infoDialog').open||$('audioDialog').open)return;
 if(e.key.toLowerCase()==='g'){e.preventDefault();guide();return;}
 if(state.phase==='choice'&&/^[1-4]$/.test(e.key)){e.preventDefault();const i=Number(e.key)-1,b=$('choices').children[i];if(b)answer(shownOptions[i],i,b);}
 if(e.key==='Enter'&&!e.target.matches('button,a,summary')){if(state.phase==='dialogue'){e.preventDefault();nextLine();}else if(state.phase==='feedback'){e.preventDefault();continueGame();}}
});
setMotion(prefersReduced);
// Exposed only as a named object for educator testing; no secrets or services.
window.AuditGame={start,nextLine,showChoices,answer,continueGame,returnCheckpoint,guide,evidence,notebook,caseMap,downloadReview,audio,getState:()=>state,getOptions:()=>shownOptions,DECISIONS,CHAPTERS,FIELD_GUIDE};
